<?php $editing=is_array($entry);$v=static fn($k)=>(string)($entry[$k]??'');$pid=$fixedProject['id']??($entry['project_id']??'');?>
<h2 class="page-title mb-4"><?=e($title)?></h2><form class="card" method="post" action="<?=$editing?'/project-costs/'.(int)$entry['id'].'/edit':'/projects/'.(int)$pid.'/costs'?>"><div class="card-body"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><input type="hidden" name="project_id" value="<?=(int)$pid?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">المشروع</label><input class="form-control" disabled value="<?=e(($fixedProject['project_code']??$entry['project_code']).' - '.($fixedProject['name']??$entry['project_name']))?>"></div><div class="col-md-6"><label class="form-label required">التاريخ</label><input class="form-control" type="date" name="cost_date" required value="<?=e($v('cost_date')?:date('Y-m-d'))?>"></div><div class="col-md-6"><label class="form-label required">كود التكلفة</label><select class="form-select js-tom-select" id="project-cost-code" name="cost_code_id" required><option value="">اختر كود التكلفة</option><?php foreach($codes as$c):if((!$c['is_active']||!$c['section_active'])&&$v('cost_code_id')!==(string)$c['id'])continue;?><option value="<?=$c['id']?>" data-section="<?=e($c['section_code'].' - '.$c['section_name'])?>" <?=$v('cost_code_id')===(string)$c['id']?'selected':''?>><?=e($c['cost_code'].' - '.$c['name'])?></option><?php endforeach;?></select><div class="form-hint" id="project-cost-section"></div></div><div class="col-md-6"><label class="form-label">المورد</label><select class="form-select js-tom-select" name="vendor_id"><option value="">بدون مورد</option><?php foreach($vendors as$x):if(!$x['is_active']&&$v('vendor_id')!==(string)$x['id'])continue;?><option value="<?=$x['id']?>" <?=$v('vendor_id')===(string)$x['id']?'selected':''?>><?=e($x['vendor_code'].' - '.$x['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label required">الوصف</label><input class="form-control" name="description" maxlength="500" required value="<?=e($v('description'))?>"></div><div class="col-md-6"><label class="form-label">الرقم المرجعي</label><input class="form-control" name="reference_number" maxlength="190" value="<?=e($v('reference_number'))?>"></div><div class="col-md-6"><label class="form-label required">المبلغ</label><input class="form-control" name="amount" inputmode="decimal" required value="<?=e($v('amount'))?>"></div><div class="col-12"><label class="form-label">ملاحظات</label><textarea class="form-control" name="notes" maxlength="5000"><?=e($v('notes'))?></textarea></div></div></div><div class="card-footer"><button class="btn btn-primary">حفظ</button></div></form><script src="/assets/js/modules/project-cost-form.js" defer></script>
